ALTER TABLE public.profiles ADD COLUMN age integer, ADD COLUMN gender text, ADD COLUMN college text, ADD COLUMN degree_program text, ADD COLUMN student_level text, ADD COLUMN academic_year text, ADD COLUMN avatar text DEFAULT 'cloud';
CREATE OR REPLACE FUNCTION public.validate_student_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN IF NEW.email IS NULL OR NEW.email !~* '^[^[:space:]@]+@asu\.edu$' THEN RAISE EXCEPTION 'Please use your @asu.edu email to create an OASIS account.'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER oasis_validate_student_signup BEFORE INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.validate_student_signup();
CREATE OR REPLACE FUNCTION public.validate_student_profile() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF NEW.age IS NOT NULL AND (NEW.age < 13 OR NEW.age > 120) THEN RAISE EXCEPTION 'Age must be between 13 and 120.'; END IF; IF NEW.avatar IS NOT NULL AND NEW.avatar NOT IN ('cloud','sun','cactus','bear','penguin','moon','turtle','star') THEN RAISE EXCEPTION 'Choose an OASIS avatar.'; END IF; IF length(NEW.preferred_name) > 40 OR length(NEW.college) > 120 OR length(NEW.degree_program) > 120 THEN RAISE EXCEPTION 'Profile text is too long.'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER oasis_validate_profile BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.validate_student_profile();